BEGIN READ ONLY; SET LOCAL TimeZone='UTC';
SELECT json_build_object('native',to_jsonb(ts),'canonical',to_char(ts AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN extract(microseconds FROM ts)::bigint % 1000000 = 0 THEN 'Z' ELSE '.'||to_char(ts AT TIME ZONE 'UTC','US')||'Z' END)::text FROM (SELECT convert_from(decode('323032362d31302d30365430303a30303a30315a','hex'),'UTF8')::timestamptz AS ts) q;
